patch:
diff --git a/repro/use-strict.js b/repro/use-strict.js
new file mode 100644
index 0000000..ccd27d8
--- /dev/null
+++ b/repro/use-strict.js
@@ -0,0 +1,13 @@
+"use strict";
+// Repro for eslint#19637: no-unused-expressions reports "use strict" with ecmaVersion: 3 in 9.25.0.
+const { Linter } = require("../lib/api");
+const linter = new Linter({ configType: "flat" });
+const code = "'use strict';\nfunction f() { 'use strict'; }\n";
+let failed = false;
+for (const ecmaVersion of [3, 5, "latest"]) {
+	const msgs = linter.verify(code, [{ languageOptions: { ecmaVersion, sourceType: "script" }, rules: { "no-unused-expressions": "error" } }], "x.js");
+	console.log(`ecmaVersion=${ecmaVersion}:`, msgs.length ? msgs.map(m => `${m.line}:${m.column} ${m.message}`) : "no errors");
+	if (msgs.length) failed = true;
+}
+console.log(failed ? "BUG: directives reported as unused expressions" : "OK");
+process.exitCode = failed ? 1 : 0;
